import json
import os
import urllib.parse
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PORT = int(os.environ.get("PORT", "8000"))
HOST = "127.0.0.1"

# In-memory store
_books = {}
_next_id = 1

def _find_book_by_id(id):
    return _books.get(id)

class Handler(BaseHTTPRequestHandler):
    def _send_json(self, code, obj):
        body = json.dumps(obj).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _send_error(self, code, message):
        body = json.dumps({"error": message}).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self):
        global _next_id
        if self.path.startswith("/books"):
            length = int(self.headers.get("Content-Length", 0))
            raw = self.rfile.read(length).decode("utf-8")
            try:
                data = json.loads(raw)
            except json.JSONDecodeError:
                self._send_error(400, "invalid JSON")
                return
            if not isinstance(data, dict):
                self._send_error(400, "not a JSON object")
                return
            if "id" in data:
                self._send_error(400, "id supplied in create body")
                return
            # validate required fields
            for field in ("title", "author", "isbn"):
                if field not in data or not isinstance(data[field], str) or not data[field].strip():
                    self._send_error(400, field)
                    return
            title = data["title"]
            author = data["author"]
            isbn = data["isbn"]
            synopsis = data.get("synopsis", "")
            book = {"id": _next_id, "title": title, "author": author, "isbn": isbn, "synopsis": synopsis}
            _next_id += 1
            _books[_next_id - 1] = book
            self._send_json(201, book)
        else:
            self._send_error(404, "not found")

    def do_GET(self):
        if self.path.startswith("/books"):
            params = urllib.parse.parse_qs(self.path[len("/books"):].split("?")[1]) if "?" in self.path else {}
            # filter
            filtered = _books.copy()
            for key, val in params.items():
                if key in ("id", "title", "author", "isbn", "synopsis", "q"):
                    filter_val = val[0]
                else:
                    continue
                if key == "id":
                    if isinstance(filter_val, str):
                        target_ids = set(int(v) for v in filter_val)
                    else:
                        target_ids = set()
                else:
                    if not filter_val:
                        continue
                    target_ids = set()
                    for book in filtered.values():
                        if (str(book.get(key, ""))).lower() == filter_val.lower():
                            target_ids.add(book["id"])
                filtered = {i: v for i, v in filtered.items() if i in target_ids}
            if not filtered:
                self._send_json(200, [])
                return
            sorted_books = sorted(filtered.values(), key=lambda b: b["id"])
            self._send_json(200, sorted_books)
        else:
            self._send_error(404, "not found")

    def do_PUT(self):
        path = self.path
        if path.startswith("/books/"):
            parts = path.split("/")
            if len(parts) != 4:
                self._send_error(404, "not found")
                return
            b_id = parts[2]
            try:
                b_id = int(b_id)
            except ValueError:
                self._send_error(404, "not found")
                return
            length = int(self.headers.get("Content-Length", 0))
            raw = self.rfile.read(length).decode("utf-8")
            try:
                data = json.loads(raw)
            except json.JSONDecodeError:
                self._send_error(400, "invalid JSON")
                return
            if not isinstance(data, dict):
                self._send_error(400, "not a JSON object")
                return
            if "id" in data:
                self._send_error(400, "id supplied in update body")
                return
            for field in ("title", "author", "isbn"):
                if field not in data or not isinstance(data[field], str) or not data[field].strip():
                    self._send_error(400, field)
                    return
            book = _books.get(b_id)
            if book is None:
                self._send_error(404, "not found")
                return
            title = data["title"]
            author = data["author"]
            isbn = data["isbn"]
            synopsis = data.get("synopsis", "")
            _books[b_id] = {"id": b_id, "title": title, "author": author, "isbn": isbn, "synopsis": synopsis}
            self._send_json(200, _books[b_id])
        else:
            self._send_error(404, "not found")

    def do_DELETE(self):
        path = self.path
        if path.startswith("/books/"):
            parts = path.split("/")
            if len(parts) != 4:
                self._send_error(404, "not found")
                return
            b_id = int(parts[2])
            if b_id not in _books:
                self._send_error(404, "not found")
                return
            del _books[b_id]
            self._send_response(204)
        else:
            self._send_error(404, "not found")

    def _send_response(self, code):
        self.send_response(code)
        self.end_headers()

def run():
    server = ThreadingHTTPServer((HOST, PORT), Handler)
    server.serve_forever()

if __name__ == "__main__":
    run()
